213	    { doi empty$ adddoi uand
214	        { pubmed empty$ addpubmed uand
215	            { eprint empty$ addeprints uand
216	                { url empty$
217	                    { "" }
218	                    { url }
219	                  if$ }
220	                { eprinturl eprint * }
221	              if$ }
222	            { pubmedurl pubmed * }
223	          if$ }
